            <p>You have successfully logged into BlueMind v5. This secure environment demonstrates best practices for authentication and messaging systems.</p>
        </div>

        <div class="messages-section">
            <div class="section-header">
                Your Messages
            </div>
            <div class="messages-list">
                <% if (typeof messages !== 'undefined' && messages.length > 0) { %>
                    <% messages.forEach(function(message) { %>
                        <div class="message">
