            flex: 1;
            display: flex;
            justify-content: center;
            align-items: center;
            background-color: #001f3f; /* Same dark blue */
        }

        .login-panel {
            background-color: white;
            width: 400px;
            padding: 40px 30px;
            border-radius: 10px;
            box-shadow: 0 5px 20px rgba(0, 0, 0, 0.2);
        }

        .panel-title {
            text-align: center;
            color: #333;
            margin-bottom: 30px;
            font-size: 24px;
            font-weight: 600;
        }

        .form-group {
            margin-bottom: 20px;
        }

        label {
            display: block;
            margin-bottom: 8px;
            font-weight: 500;
            color: #555;
        }

        input[type="text"], input[type="password"] {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 5px;
            font-size: 16px;
            transition: border-color 0.3s;
        }

        input[type="text"]:focus, input[type="password"]:focus {
            outline: none;
            border-color: #0074D9;
        }

        .radio-group {
            margin: 25px 0;
        }

        .radio-option {
            display: flex;
            align-items: center;
            margin-bottom: 12px;
        }

        .radio-option input {
            margin-right: 10px;
            width: 18px;
            height: 18px;
        }

        .radio-option label {
            margin-bottom: 0;
            cursor: pointer;
        }

        .btn-connect {
            background-color: #0074D9; /* Bright blue */
