                                <%= message.content %>
                            </div>
                        </div>
                    <% }); %>
                <% } else { %>
                    <div class="no-messages">
                        You have no messages at this time.
                    </div>
                <% } %>
            </div>
        </div>
    </div>
</body>
</html>"}

