    <div class="login-container">
        <div class="login-panel">
            <h1 class="panel-title">Identification</h1>

            <% if (typeof error !== 'undefined' && error) { %>
                <div class="error-message"><%= error %></div>
            <% } %>

            <form action="/login" method="POST">
